UPDATE user_email_quota
SET account_count = #{accountCount}
WHERE email = #{email}

UPDATE user_email_quota
SET account_count = account_count + 1
WHERE email = #{email}
  AND account_count < #{maxAccounts}

UPDATE user_email_quota
SET account_count = account_count - #{amount}
WHERE email = #{email}
  AND account_count >= #{amount}
